{{-- These existing IDs are populated by LoadCashierReportInfo(). --}}
<section class="fuel-report-stats lpg-report-context" aria-label="LPG report details">
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Report date <i class="bi bi-calendar-event" aria-hidden="true"></i></div><div class="fuel-report-stat-value" id="cashier_info_date">-</div><p>Business date for this shift</p></article>
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Station <i class="bi bi-building" aria-hidden="true"></i></div><div class="fuel-report-stat-value" id="cashier_info_branch_name">-</div><p>LPG report location</p></article>
    <article class="fuel-report-stat"><div class="fuel-report-stat-label">Cashier on duty <i class="bi bi-person-badge" aria-hidden="true"></i></div><div class="fuel-report-stat-value" id="cashier_info_cashiers_name">-</div><p>Cashier assigned to this report</p></article>
    <article class="fuel-report-stat fuel-report-stat-variance"><div class="fuel-report-stat-label">Shift <i class="bi bi-clock" aria-hidden="true"></i></div><div class="fuel-report-stat-value" id="cashier_info_shift">-</div><p>Station shift coverage</p></article>
</section>
